#!/bin/sh
# ATT&CKWISE API container start: refuse to start without a stable APP_KEY or with debug on,
# make sure the persistent ATT&CK cache is writable, cache Laravel config/routes in tmpfs, then
# hand over to PHP-FPM. Never generates or prints APP_KEY (see attackwise.sh init).
set -eu

fail() { echo "attackwise-api: $*" >&2; exit 1; }

[ -n "${APP_KEY:-}" ] || fail "APP_KEY is empty. Run './attackwise.sh init' once and keep the generated config file."
case "$APP_KEY" in
    base64:*) ;;
    *) fail "APP_KEY must look like base64:… (generated by './attackwise.sh init')." ;;
esac
[ "${APP_ENV:-}" = "production" ] || fail "APP_ENV must be production in this image."
case "${APP_DEBUG:-false}" in
    false|0|"") ;;
    *) fail "APP_DEBUG must be false in production." ;;
esac

cache_dir="${ATTACKWISE_CACHE_DIR:-/var/lib/attackwise/attack-cache}"
mkdir -p "$cache_dir" || fail "cannot create $cache_dir"
probe="$cache_dir/.write-probe-$$"
( : > "$probe" ) 2>/dev/null || fail "$cache_dir is not writable by $(id -un)."
rm -f "$probe"

# Writable runtime directories live on tmpfs (compose.yaml); recreate their structure.
mkdir -p /tmp/laravel storage/framework/cache/data storage/framework/views storage/framework/sessions storage/logs

if [ "${1:-}" = "php-fpm" ]; then
    php artisan config:cache --no-interaction > /dev/null
    php artisan route:cache --no-interaction > /dev/null
    php artisan event:cache --no-interaction > /dev/null
fi

exec "$@"
